from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Any, Callable, List, Optional, Sequence, Union
import os
if not os.path.exists(output_dir):
    os.makedirs(output_dir)

# If fast_dev_run is True, only process a subset of inputs for testing
if fast_dev_run:
    inputs = inputs[:10]  # Process only the first 10 inputs for example

# Reorder files by size if required
if reorder_files:
    inputs = sorted(inputs, key=lambda x: os.path.getsize(x))

# If chunk_size is set, split inputs into chunks
if chunk_size is not None:
    inputs = [inputs[i:i + chunk_size] for i in range(0, len(inputs), chunk_size)]

# Define the function to process each input or chunk
def process_input(input_data):
    # If batch_size is set, process inputs in batches
    if batch_size is not None:
        for i in range(0, len(input_data), batch_size):
            batch = input_data[i:i + batch_size]
            results = [fn(item) for item in batch]
    else:
        results = fn(input_data)

    # Save the processed data to the output directory
    # Assuming the function returns a filename or some identifier
    output_path = os.path.join(output_dir, str(results))
    with open(output_path, 'w') as f:
        f.write(str(results))

# Process inputs in parallel if num_workers is set
if num_workers is not None:
    with ThreadPoolExecutor(max_workers=num_workers) as executor:
        future_to_input = {executor.submit(process_input, inp): inp for inp in inputs}
        for future in as_completed(future_to_input):
            input_data = future_to_input[future]
            try:
                future.result()
            except Exception as exc:
                print(f'Input {input_data} generated an exception: {exc}')
else:
    # Process inputs sequentially
    for input_data in inputs:
        process_input(input_data)

# If compression is set, compress the output directory
if compression is not None:
    shutil.make_archive(output_dir, compression, output_dir)

print(f'Optimization complete. Processed data is stored in {output_dir}')

