def higham_algorithm(A, max_iterations):
    # Higham algorithm
    n = A.shape[0]
    Y = A
    for _ in range(max_iterations):
        R = np.linalg.cholesky(Y)
        L = np.linalg.inv(R)
        Y = 0.5 * (Y + L.T @ L)
    return Y

def clip_eigenvalues(A):
    # Clipping negative eigenvalues
    s, u = np.linalg.eigh(A)
    H = np.dot(u, np.dot(np.diag(np.maximum(s, 0)), u.T))
    A_nearest = (A + H) / 2
    A_nearest = (A_nearest + A_nearest.T) / 2
    return A_nearest

