import numpy as np
def higham_algorithm(A, max_iterations):
    # Higham algorithm
    n = A.shape[0]
    Y = A.copy()
    for _ in range(max_iterations):
        R = Y - np.tril(Y, -1).T
        X = (R + R.T) / 2
        eigvals, eigvecs = np.linalg.eigh(X)
        D = np.diag(np.maximum(eigvals, 0))
        Y = eigvecs @ D @ eigvecs.T
        norm_diff = np.linalg.norm(Y - X, 'fro')
        if norm_diff < 1e-6:
            break
    return Y

def clip_eigenvalues(A):
    # Eigenvalue clipping method
    eigvals, eigvecs = np.linalg.eigh(A)
    eigvals_clipped = np.clip(eigvals, a_min=0, a_max=None)
    A_nearest = eigvecs @ np.diag(eigvals_clipped) @ eigvecs.T
    return A_nearest

if higham:
    return higham_algorithm(cov, higham_max_iteration)
else:
    return clip_eigenvalues(cov)

import numpy as np
def project_to_psd(matrix):
    """Projects a symmetric matrix to the positive semi-definite cone by clipping negative eigenvalues."""
    s, u = np.linalg.eigh(matrix)
    s[s < 0] = 0
    return np.dot(u, np.dot(np.diag(s), u.T))

def higham_algorithm(matrix, max_iterations):
    """Finds the nearest positive definite matrix using the Higham (2002) algorithm."""
    Y = matrix
    for _ in range(max_iterations):
        R = project_to_psd(Y)
        Y = (R + R.T) / 2
        deltaS = Y - matrix
        Y = matrix + deltaS - np.diag(np.diag(deltaS))
        if np.all(np.linalg.eigvals(Y) > 0):
            return Y
    return Y

if higham:
    return higham_algorithm(cov, higham_max_iteration)
else:
    return project_to_psd(cov)

