import numpy as np
def interpolate_trilinear(volume, loc):
    # Compute the integer and fractional parts of the location
    loc_floor = np.floor(loc).astype(int)
    loc_frac = loc - loc_floor

    # Gather the 8 neighboring points for interpolation
    neighbors = []
    for dz in range(2):
        for dy in range(2):
            for dx in range(2):
                neighbor_loc = loc_floor + np.array([dz, dy, dx])
                if edge_behavior == 'CONSTANT_OUTSIDE':
                    if np.any(neighbor_loc < 0) or np.any(neighbor_loc >= np.array(volume.shape)):
                        neighbors.append(constant_values)
                    else:
                        neighbors.append(volume[tuple(neighbor_loc)])
                elif edge_behavior == 'CLAMP':
                    neighbor_loc = np.clip(neighbor_loc, 0, np.array(volume.shape) - 1)
                    neighbors.append(volume[tuple(neighbor_loc)])

    # Perform trilinear interpolation
    c00 = neighbors[0] * (1 - loc_frac[0]) + neighbors[1] * loc_frac[0]
    c01 = neighbors[2] * (1 - loc_frac[0]) + neighbors[3] * loc_frac[0]
    c10 = neighbors[4] * (1 - loc_frac[0]) + neighbors[5] * loc_frac[0]
    c11 = neighbors[6] * (1 - loc_frac[0]) + neighbors[7] * loc_frac[0]
    c0 = c00 * (1 - loc_frac[1]) + c01 * loc_frac[1]
    c1 = c10 * (1 - loc_frac[1]) + c11 * loc_frac[1]
    value = c0 * (1 - loc_frac[2]) + c1 * loc_frac[2]
    return value

def interpolate_nearest(volume, loc):
    nearest_loc = np.round(loc).astype(int)
    if edge_behavior == 'CONSTANT_OUTSIDE':
        if np.any(nearest_loc < 0) or np.any(nearest_loc >= np.array(volume.shape)):
            return constant_values
        else:
            return volume[tuple(nearest_loc)]
    elif edge_behavior == 'CLAMP':
        nearest_loc = np.clip(nearest_loc, 0, np.array(volume.shape) - 1)
        return volume[tuple(nearest_loc)]

