        for i in range(len(simplex)):
            for j in range(i + 1, len(simplex)):
                midpoint = (vertices[simplex[i]] + vertices[simplex[j]]) / 2
                midpoint /= np.linalg.norm(midpoint)  # Normalize to unit length
                new_vertices.append(midpoint)
    vertices = np.vstack((vertices, new_vertices))
    vertices = np.unique(vertices, axis=0)  # Remove duplicates

