    if det <= 0:
        raise ValueError("Covariance matrix must have a positive determinant")

    n = matrix.shape[0]
    if mode == 'fast':
        factor = det ** (1.0 / n)
    elif mode == 'accurate':
        log_det = np.log(det)
        factor = np.exp(log_det / n)
    else:
        raise ValueError("Mode must be either 'fast' or 'accurate'")

    isotropic_cov = factor * np.eye(n)
    isotropic_covs.append(isotropic_cov)

