    # Return an empty Instances object
    return Instances(image_size)

# Create a list to hold data for each field in Instances
boxes = []
classes = []
masks = []
keypoints = []

for anno in annos:
    # Convert bbox from XYWH to XYXY format
    bbox = BoxMode.convert(anno["bbox"], anno["bbox_mode"], BoxMode.XYXY_ABS)
    boxes.append(bbox)

    classes.append(anno["category_id"])

    if "segmentation" in anno:
        if mask_format == "polygon":
            masks.append(anno["segmentation"])
        elif mask_format == "bitmask":
            masks.append(anno["segmentation"]["counts"])

    if "keypoints" in anno:
        keypoints.append(anno["keypoints"])

# Convert lists to tensors or appropriate structures
boxes = Boxes(torch.tensor(boxes, dtype=torch.float32))
classes = torch.tensor(classes, dtype=torch.int64)
if mask_format == "polygon":
    masks = PolygonMasks(masks)
elif mask_format == "bitmask":
    masks = BitMasks(torch.tensor(masks, dtype=torch.uint8))

if keypoints:
    keypoints = torch.tensor(keypoints, dtype=torch.float32)

# Create an Instances object
instances = Instances(image_size)
instances.gt_boxes = boxes
instances.gt_classes = classes

if masks:
    if mask_format == "polygon":
        instances.gt_masks = masks
    elif mask_format == "bitmask":
        instances.gt_masks = masks

if keypoints:
    instances.gt_keypoints = keypoints

return instances

