# Calculate the length of the longest common subsequence
def lcs(X, Y):
    m = len(X)
    n = len(Y)
    L = [[0] * (n + 1) for i in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                L[i][j] = 0
            elif X[i - 1] == Y[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1
            else:
                L[i][j] = max(L[i - 1][j], L[i][j - 1])
    return L[m][n]

lcs_length = lcs(continuation_tokens, reference_tokens)
precision = lcs_length / len(continuation_tokens)
recall = lcs_length / len(reference_tokens)
if precision + recall != 0:
    rouge_l_score = (2 * precision * recall) / (precision + recall)
else:
    rouge_l_score = 0.0

return rouge_l_score

