    # Initialize data structures for true positives, false positives, etc.
    tp = defaultdict(int)
    fp = defaultdict(int)
    fn = defaultdict(int)

    # Iterate over each category
    for label, category in label2cat.items():
        # Filter ground truth and detection annotations by category
        gt_annos_cat = [anno for anno in gt_annos if anno['label'] == label]
        dt_annos_cat = [anno for anno in dt_annos if anno['label'] == label]

        # Sort the detection annotations by score in descending order
        dt_annos_cat.sort(key=lambda x: x['score'], reverse=True)

        # Match detections to ground truth annotations
        for dt_anno in dt_annos_cat:
            matched = False
            for gt_anno in gt_annos_cat:
                iou = calculate_iou(dt_anno['bbox'], gt_anno['bbox'])
                if iou >= iou_threshold:
                    matched = True
                    gt_annos_cat.remove(gt_anno)  # Avoid multiple detections for the same ground truth
                    break

            if matched:
                tp[label] += 1
            else:
                fp[label] += 1

        # Remaining ground truth annotations are false negatives
        fn[label] += len(gt_annos_cat)

        # Calculate precision and recall for the current category and IoU threshold
        precision = tp[label] / (tp[label] + fp[label]) if (tp[label] + fp[label]) > 0 else 0
        recall = tp[label] / (tp[label] + fn[label]) if (tp[label] + fn[label]) > 0 else 0

        # Store the results
        results[category]['precision'].append(precision)
        results[category]['recall'].append(recall)

# Calculate mean Average Precision (mAP) and mean Average Recall (mAR) across all categories and IoU thresholds
