mar_results = {category: sum(values['recall']) / len(metric) for category, values in results.items()}

# Calculate overall mAP and mAR
overall_map = sum(map_results.values()) / len(map_results)
overall_mar = sum(mar_results.values()) / len(mar_results)

# Organize results into a dictionary
